/**
 * Heaven Holdings — Capital Partner Network (Investor Database)
 * ===============================================================
 * HOW TO DEPLOY (same pattern as your other Workers):
 *
 * 1. Cloudflare dashboard -> Workers & Pages -> Create -> Worker
 *    name it: hh-investors -> Deploy
 * 2. Click "Edit code" -> Select All (Ctrl/Cmd+A) -> Paste this whole file -> Save & Deploy
 * 3. Storage & Databases -> KV -> Create namespace -> name: INVESTORS_DATA
 * 4. Your worker -> Settings -> Bindings -> Add -> KV Namespace
 *    Variable name: INVESTORS  |  Namespace: INVESTORS_DATA
 * 5. Settings -> Variables & Secrets -> Add Secret:
 *    ADMIN_KEY -> your private password (full access)
 *    STAFF_KEY -> team password for anyone else you want to give access to (optional)
 * 6. Visit: https://hh-investors.<your-subdomain>.workers.dev
 *
 * CUSTOM DOMAIN (optional, once it works on the workers.dev URL):
 *    Worker -> Settings -> Domains & Routes -> Add custom domain
 *    e.g. investors.heavenholdingscapital.com
 *
 * WHAT'S NEW: a Correspondence tab for drafting and merging emails and
 * formal letters to your investor list (templates saved in the same KV
 * namespace, under a separate key so they never collide with your data).
 */

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === "/api/data" || url.pathname === "/api/templates") {
      if (!env.INVESTORS) return resp("KV binding INVESTORS missing — complete setup step 4", 500);
      if (!env.ADMIN_KEY) return resp("ADMIN_KEY secret missing — complete setup step 5", 500);

      const key = (request.headers.get("x-team-key") || "").trim();
      const isAdmin = safeEqual(key, env.ADMIN_KEY);
      const isStaff = env.STAFF_KEY ? safeEqual(key, env.STAFF_KEY) : false;
      if (!isAdmin && !isStaff) return new Response("Unauthorized", { status: 401 });

      const kvKey = url.pathname === "/api/templates" ? "templates" : "investors";
      const defaultVal = "[]";

      if (request.method === "GET") {
        const data = (await env.INVESTORS.get(kvKey)) || defaultVal;
        return new Response(data, { headers: { "content-type": "application/json", "cache-control": "no-store" } });
      }

      if (request.method === "PUT") {
        const body = await request.text();
        if (body.length > 1500000) return resp("Data too large", 413);
        try { JSON.parse(body); } catch { return resp("Invalid JSON", 400); }
        await env.INVESTORS.put(kvKey, body);
        const bak = kvKey + "_bak_" + new Date().toISOString().slice(0, 10);
        await env.INVESTORS.put(bak, body, { expirationTtl: 86400 * 14 });
        return new Response(JSON.stringify({ ok: true }), { headers: { "content-type": "application/json" } });
      }

      return new Response("Method not allowed", { status: 405 });
    }

    return new Response(HTML, {
      headers: {
        "content-type": "text/html;charset=utf-8",
        "cache-control": "no-store",
        "x-frame-options": "DENY"
      }
    });
  }
};

function resp(msg, status) {
  return new Response(JSON.stringify({ error: msg }), {
    status, headers: { "content-type": "application/json" }
  });
}

function safeEqual(a, b) {
  if (!a || !b || a.length !== b.length) return false;
  const e = new TextEncoder(), ab = e.encode(a), bb = e.encode(b);
  let d = 0;
  for (let i = 0; i < ab.length; i++) d |= ab[i] ^ bb[i];
  return d === 0;
}

const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Heaven Holdings \u2014 Capital Partner Network</title>\n<style>\n@import url('https://fonts.googleapis.com/css2?family=Source+Serif+4:opsz,wght@8..60,400;8..60,500;8..60,600;8..60,700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');\n\n:root{\n  --bg:#0A0F1C;\n  --panel:#10182A;\n  --panel-2:#161F35;\n  --panel-3:#1C2740;\n  --border:#243252;\n  --border-soft:#1B2540;\n  --text:#E7EAF2;\n  --text-dim:#8B93A7;\n  --text-faint:#5B6478;\n  --accent:#C7A045;\n  --accent-dim:#8A7230;\n  --accent-bg:rgba(199,160,69,0.08);\n  --positive:#5FA37C;\n  --negative:#C1594C;\n  --info:#5B7BB4;\n  --radius:2px;\n}\n*{box-sizing:border-box; margin:0; padding:0;}\nhtml,body{background:var(--bg); color:var(--text); font-family:'Inter',sans-serif; height:100%;}\nbody{font-size:14px; line-height:1.5;}\n::selection{background:var(--accent); color:#0A0F1C;}\n.mono{font-family:'JetBrains Mono',monospace;}\n.serif{font-family:'Source Serif 4',serif;}\nbutton{font-family:inherit; cursor:pointer;}\ninput,select,textarea{font-family:inherit; color:var(--text); background:transparent; border:none; outline:none;}\ninput:focus,select:focus,textarea:focus{outline:1px solid var(--accent-dim);}\na{color:var(--accent);}\n\n/* ---------- Gate ---------- */\n#gate{position:fixed; inset:0; background:var(--bg); display:flex; align-items:center; justify-content:center; z-index:100; flex-direction:column; gap:18px;}\n#gate img{width:64px; height:64px; border-radius:50%; object-fit:cover;}\n#gate .gtitle{font-family:'Source Serif 4',serif; font-size:22px; color:var(--text);}\n#gate .gtitle span{color:var(--accent);}\n#gate input{border:1px solid var(--border); background:var(--panel-2); padding:11px 14px; border-radius:var(--radius); width:280px; text-align:center; letter-spacing:0.08em;}\n#gate button{background:var(--accent); color:#12100A; border:none; padding:11px 18px; font-weight:700; font-size:12px; letter-spacing:0.05em; text-transform:uppercase; border-radius:var(--radius);}\n#gate .gerr{color:var(--negative); font-size:12px; height:14px;}\n\n/* ---------- Banner / Header ---------- */\n#banner{\n  background:linear-gradient(120deg, #0A0F1C 0%, #121A2E 55%, #171F36 100%);\n  border-bottom:1px solid var(--border);\n  padding:26px 28px 22px;\n  position:relative;\n  overflow:hidden;\n}\n#banner::before{\n  content:\"\"; position:absolute; inset:0;\n  background:\n    linear-gradient(90deg, rgba(199,160,69,0.10), transparent 40%),\n    repeating-linear-gradient(115deg, rgba(199,160,69,0.05) 0 1px, transparent 1px 90px);\n  pointer-events:none;\n}\n.banner-inner{display:flex; align-items:center; gap:18px; position:relative; z-index:1;}\n.banner-logo{height:52px; width:52px; border-radius:50%; object-fit:cover; flex-shrink:0; box-shadow:0 0 0 1px var(--accent-dim), 0 6px 18px rgba(0,0,0,0.4);}\n.banner-text .bname{font-family:'Source Serif 4',serif; font-size:24px; font-weight:600; letter-spacing:0.01em; color:var(--text);}\n.banner-text .bname span{color:var(--accent);}\n.banner-text .bsub{font-family:'JetBrains Mono',monospace; font-size:10.5px; letter-spacing:0.16em; color:var(--text-dim); text-transform:uppercase; margin-top:4px;}\n.banner-right{margin-left:auto; display:flex; gap:26px; position:relative; z-index:1;}\n.bstat{text-align:right;}\n.bstat .v{font-family:'JetBrains Mono',monospace; font-size:19px; color:var(--accent); font-weight:600;}\n.bstat .l{font-family:'JetBrains Mono',monospace; font-size:9px; letter-spacing:0.12em; color:var(--text-faint); text-transform:uppercase; margin-top:2px;}\n\n/* ---------- Toolbar ---------- */\n#toolbar{\n  position:sticky; top:0; z-index:40;\n  display:flex; align-items:center; gap:10px; flex-wrap:wrap;\n  padding:14px 24px; background:var(--panel); border-bottom:1px solid var(--border);\n}\n#toolbar input[type=\"search\"]{\n  background:var(--panel-2); border:1px solid var(--border); padding:9px 12px; border-radius:var(--radius);\n  width:220px; font-size:13px;\n}\n#toolbar select{\n  background:var(--panel-2); border:1px solid var(--border); padding:9px 10px; border-radius:var(--radius); font-size:13px;\n}\n.btn-primary{background:var(--accent); color:#12100A; border:none; padding:9px 15px; font-size:12px; font-weight:700; letter-spacing:0.04em; text-transform:uppercase; border-radius:var(--radius);}\n.btn-primary:hover{background:#D8B15A;}\n.btn-primary:disabled{background:var(--panel-3); color:var(--text-faint); cursor:default;}\n.btn-ghost{background:transparent; border:1px solid var(--border); color:var(--text-dim); padding:9px 13px; font-size:12px; letter-spacing:0.03em; border-radius:var(--radius);}\n.btn-ghost:hover{border-color:var(--accent-dim); color:var(--text);}\n.btn-ghost:disabled{opacity:0.4; cursor:default;}\n.btn-danger{background:transparent; border:1px solid var(--negative); color:var(--negative); padding:9px 13px; font-size:12px; border-radius:var(--radius);}\n.spacer{flex:1;}\n.savebadge{font-family:'JetBrains Mono',monospace; font-size:10px; letter-spacing:0.08em; text-transform:uppercase; color:var(--text-faint);}\n.savebadge.saving{color:var(--info);}\n.savebadge.saved{color:var(--positive);}\n.savebadge.error{color:var(--negative);}\n\n/* ---------- Main / Table ---------- */\n#main{padding:20px 24px; max-width:1500px; margin:0 auto;}\n.tbl-wrap{overflow-x:auto; border:1px solid var(--border); border-radius:var(--radius); background:var(--panel);}\ntable.invtbl{width:100%; border-collapse:collapse; font-size:13px;}\ntable.invtbl th{\n  text-align:left; padding:10px 12px; font-family:'JetBrains Mono',monospace; font-size:10px;\n  letter-spacing:0.08em; text-transform:uppercase; color:var(--text-faint); border-bottom:1px solid var(--border);\n  background:var(--panel-2); white-space:nowrap;\n}\ntable.invtbl td{padding:8px 12px; border-bottom:1px solid var(--border-soft); vertical-align:top;}\ntable.invtbl tr:last-child td{border-bottom:none;}\ntable.invtbl tr:hover td{background:rgba(199,160,69,0.03);}\ntable.invtbl input, table.invtbl textarea{\n  width:100%; background:transparent; border:1px solid transparent; padding:4px 5px; border-radius:2px; font-size:13px; color:var(--text);\n}\ntable.invtbl input:hover, table.invtbl textarea:hover{border-color:var(--border);}\ntable.invtbl input:focus, table.invtbl textarea:focus{border-color:var(--accent-dim); background:var(--panel-2);}\ntable.invtbl textarea{resize:vertical; min-height:32px;}\n.col-check{width:34px; text-align:center;}\n.col-status{width:150px;}\n.col-actions{width:44px; text-align:center;}\n.status-select{\n  padding:5px 8px; border-radius:12px; font-size:11px; font-weight:600; border:1px solid transparent;\n  appearance:none; -webkit-appearance:none; cursor:pointer; width:100%;\n}\n.xbtn{background:transparent; border:none; color:var(--text-faint); font-size:16px; line-height:1;}\n.xbtn:hover{color:var(--negative);}\n.empty{padding:50px 20px; text-align:center; color:var(--text-faint); font-style:italic;}\n.rowcount{font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--text-faint); margin-top:10px;}\n\n/* ---------- Modal (copy emails) ---------- */\n#modal-bg{position:fixed; inset:0; background:rgba(0,0,0,0.55); display:none; align-items:center; justify-content:center; z-index:80;}\n#modal-bg.show{display:flex;}\n#modal{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius); padding:22px; width:480px; max-width:90vw;}\n#modal h3{font-family:'Source Serif 4',serif; font-size:16px; margin-bottom:10px;}\n#modal textarea{width:100%; height:120px; background:var(--panel-2); border:1px solid var(--border); padding:10px; font-size:12px; font-family:'JetBrains Mono',monospace; color:var(--text-dim);}\n#modal .mrow{display:flex; gap:8px; justify-content:flex-end; margin-top:14px;}\n\n/* ---------- Top nav ---------- */\n#topnav{display:flex; gap:4px; padding:10px 24px 0; background:var(--panel); border-bottom:1px solid var(--border);}\n.tnbtn{background:transparent; border:none; color:var(--text-dim); padding:10px 16px; font-size:12.5px; font-weight:600; letter-spacing:0.02em; border-bottom:2px solid transparent; border-radius:2px 2px 0 0;}\n.tnbtn:hover{color:var(--text);}\n.tnbtn.on{color:var(--accent); border-bottom-color:var(--accent);}\n.btn-primary.sm, .btn-ghost.sm{padding:6px 11px; font-size:11px;}\n\n/* ---------- Correspondence ---------- */\n#corr-wrap{display:grid; grid-template-columns:220px 1fr 1fr; gap:16px; padding:20px 24px; max-width:1600px; margin:0 auto; align-items:start;}\n.corr-panel-head{display:flex; align-items:center; justify-content:space-between; margin-bottom:10px;}\n.corr-panel-head h3{font-family:'Source Serif 4',serif; font-size:14px; font-weight:600; color:var(--text);}\n#corr-templates, #corr-editor, #corr-compose{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius); padding:14px;}\n#template-list{display:flex; flex-direction:column; gap:4px;}\n.tpl-item{display:flex; align-items:center; justify-content:space-between; padding:8px 10px; border-radius:2px; cursor:pointer; font-size:12.5px; color:var(--text-dim); border:1px solid transparent;}\n.tpl-item:hover{background:var(--panel-2);}\n.tpl-item.on{background:var(--accent-bg); border-color:var(--accent-dim); color:var(--text);}\n.tpl-item .tpl-badge{font-family:'JetBrains Mono',monospace; font-size:9px; text-transform:uppercase; letter-spacing:0.06em; color:var(--text-faint); padding:2px 6px; border:1px solid var(--border); border-radius:8px;}\n.fld{display:block; font-family:'JetBrains Mono',monospace; font-size:10px; letter-spacing:0.08em; text-transform:uppercase; color:var(--text-faint); margin-bottom:12px;}\n.fld input, .fld select, .fld textarea{\n  display:block; width:100%; margin-top:6px; background:var(--panel-2); border:1px solid var(--border);\n  padding:9px 10px; border-radius:2px; font-size:13px; color:var(--text); text-transform:none; letter-spacing:normal; font-family:'Inter',sans-serif;\n}\n.fld textarea{font-family:'JetBrains Mono',monospace; font-size:12.5px; line-height:1.6;}\n.corr-tokens{font-size:11.5px; color:var(--text-faint); line-height:2.2;}\n.tokchip{background:var(--panel-2); border:1px solid var(--border); color:var(--accent); font-family:'JetBrains Mono',monospace; font-size:10.5px; padding:3px 8px; border-radius:10px; margin:0 4px 4px 0;}\n.tokchip:hover{border-color:var(--accent-dim);}\n.grid2{display:grid; grid-template-columns:1fr 1fr; gap:12px;}\n#compose-list{display:flex; flex-direction:column; gap:10px; max-height:520px; overflow-y:auto; margin:14px 0;}\n.compose-card{border:1px solid var(--border); border-radius:2px; padding:12px; background:var(--panel-2);}\n.compose-card .cc-head{display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;}\n.compose-card .cc-name{font-weight:600; font-size:13px;}\n.compose-card .cc-email{font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--text-faint);}\n.compose-card .cc-subject{font-size:12px; color:var(--text-dim); margin-bottom:6px;}\n.compose-card pre{white-space:pre-wrap; font-family:'JetBrains Mono',monospace; font-size:11.5px; color:var(--text-dim); background:var(--panel); border:1px solid var(--border-soft); padding:10px; border-radius:2px; max-height:180px; overflow-y:auto;}\n.compose-card .cc-actions{display:flex; gap:8px; margin-top:8px;}\n.compose-card.noemail .cc-actions .btn-primary{display:none;}\n.compose-card .cc-warn{color:var(--negative); font-size:11px; margin-top:4px;}\n.mark-contacted-row{font-size:12.5px; color:var(--text-dim); padding-top:10px; border-top:1px solid var(--border-soft);}\n.card-note{color:var(--text-faint); font-size:12.5px; font-style:italic; padding:20px 0;}\n#corr-letters-actions{display:flex; gap:10px; margin-bottom:12px;}\n\n@media (max-width:1100px){\n  #corr-wrap{grid-template-columns:1fr; }\n}\n@media (max-width:760px){\n  .banner-right{display:none;}\n  #toolbar input[type=\"search\"]{width:140px;}\n}\n</style>\n</head>\n<body>\n\n<div id=\"gate\">\n  <img src=\"data:image/jpeg;base64,\" alt=\"Heaven Holdings\">\n  <div class=\"gtitle\">Heaven Holdings <span>Capital Partner Network</span></div>\n  <input id=\"gate-key\" type=\"password\" placeholder=\"Access key\" autocomplete=\"off\">\n  <button id=\"gate-btn\">Enter</button>\n  <div class=\"gerr\" id=\"gate-err\"></div>\n</div>\n\n<div id=\"app\" style=\"display:none;\">\n  <div id=\"banner\">\n    <div class=\"banner-inner\">\n      <img class=\"banner-logo\" src=\"data:image/jpeg;base64,\" alt=\"Heaven Holdings\">\n      <div class=\"banner-text\">\n        <div class=\"bname\">Heaven Holdings <span>Capital Partner Network</span></div>\n        <div class=\"bsub\">Family Offices \u00b7 Angel Investors \u00b7 JV Partners \u00b7 Financiers \u00b7 Capitalists</div>\n      </div>\n      <div class=\"banner-right\">\n        <div class=\"bstat\"><div class=\"v\" id=\"stat-total\">0</div><div class=\"l\">Total</div></div>\n        <div class=\"bstat\"><div class=\"v\" id=\"stat-active\">0</div><div class=\"l\">Active</div></div>\n        <div class=\"bstat\"><div class=\"v\" id=\"stat-selected\">0</div><div class=\"l\">Selected</div></div>\n      </div>\n    </div>\n  </div>\n\n  <div id=\"topnav\">\n    <button class=\"tnbtn on\" id=\"tab-directory\">Directory</button>\n    <button class=\"tnbtn\" id=\"tab-correspondence\">Correspondence</button>\n  </div>\n\n  <div id=\"view-directory\">\n    <div id=\"toolbar\">\n      <input type=\"search\" id=\"search\" placeholder=\"Search company, contact, email...\">\n      <select id=\"filter-status\">\n        <option value=\"\">All statuses</option>\n      </select>\n      <button class=\"btn-ghost\" id=\"btn-selectall\">Select all filtered</button>\n      <button class=\"btn-ghost\" id=\"btn-clearsel\">Clear selection</button>\n      <button class=\"btn-primary\" id=\"btn-email\" disabled>Email selected</button>\n      <button class=\"btn-ghost\" id=\"btn-copyemails\" disabled>Copy emails</button>\n      <button class=\"btn-primary\" id=\"btn-compose\" disabled>Compose correspondence</button>\n      <div class=\"spacer\"></div>\n      <button class=\"btn-ghost\" id=\"btn-export\">Export CSV</button>\n      <button class=\"btn-ghost\" id=\"btn-import\">Import CSV</button>\n      <input type=\"file\" id=\"file-import\" accept=\".csv\" style=\"display:none;\">\n      <button class=\"btn-primary\" id=\"btn-add\">+ Add entry</button>\n      <span class=\"savebadge\" id=\"savebadge\"></span>\n    </div>\n\n    <div id=\"main\">\n      <div class=\"tbl-wrap\">\n        <table class=\"invtbl\">\n          <thead>\n            <tr>\n              <th class=\"col-check\"><input type=\"checkbox\" id=\"check-header\"></th>\n              <th>Company / Office</th>\n              <th>Contact Person</th>\n              <th>Office Address</th>\n              <th>Phone</th>\n              <th>Email</th>\n              <th class=\"col-status\">Status</th>\n              <th class=\"col-actions\"></th>\n            </tr>\n          </thead>\n          <tbody id=\"tbody\"></tbody>\n        </table>\n        <div class=\"empty\" id=\"empty-msg\" style=\"display:none;\">No entries yet \u2014 click \"+ Add entry\" to start building your investor list.</div>\n      </div>\n      <div class=\"rowcount\" id=\"rowcount\"></div>\n    </div>\n  </div>\n\n  <div id=\"view-correspondence\" style=\"display:none;\">\n    <div id=\"corr-wrap\">\n\n      <div id=\"corr-templates\">\n        <div class=\"corr-panel-head\">\n          <h3>Templates</h3>\n          <button class=\"btn-primary sm\" id=\"btn-new-template\">+ New</button>\n        </div>\n        <div id=\"template-list\"></div>\n      </div>\n\n      <div id=\"corr-editor\">\n        <div class=\"corr-panel-head\">\n          <h3>Edit template</h3>\n          <div>\n            <button class=\"btn-ghost sm\" id=\"btn-delete-template\" disabled>Delete</button>\n            <button class=\"btn-primary sm\" id=\"btn-save-template\" disabled>Save</button>\n          </div>\n        </div>\n        <div id=\"editor-body\" style=\"display:none;\">\n          <label class=\"fld\">Name<input type=\"text\" id=\"tpl-name\" placeholder=\"e.g. Initial Introduction\"></label>\n          <label class=\"fld\">Type\n            <select id=\"tpl-type\">\n              <option value=\"email\">Email</option>\n              <option value=\"letter\">Formal Letter</option>\n            </select>\n          </label>\n          <label class=\"fld\" id=\"tpl-subject-wrap\">Subject<input type=\"text\" id=\"tpl-subject\" placeholder=\"Subject line\"></label>\n          <label class=\"fld\">Body\n            <textarea id=\"tpl-body\" rows=\"12\" placeholder=\"Dear {{first_name}},&#10;&#10;...\"></textarea>\n          </label>\n          <div class=\"corr-tokens\">\n            Insert field: <button class=\"tokchip\" data-t=\"{{company}}\">company</button><button class=\"tokchip\" data-t=\"{{contact}}\">contact</button><button class=\"tokchip\" data-t=\"{{first_name}}\">first_name</button><button class=\"tokchip\" data-t=\"{{address}}\">address</button><button class=\"tokchip\" data-t=\"{{phone}}\">phone</button><button class=\"tokchip\" data-t=\"{{email}}\">email</button><button class=\"tokchip\" data-t=\"{{status}}\">status</button><button class=\"tokchip\" data-t=\"{{date}}\">date</button><button class=\"tokchip\" data-t=\"{{sender_name}}\">sender_name</button><button class=\"tokchip\" data-t=\"{{sender_title}}\">sender_title</button>\n          </div>\n        </div>\n        <div id=\"editor-empty\" class=\"card-note\">Select a template on the left, or create a new one.</div>\n      </div>\n\n      <div id=\"corr-compose\">\n        <div class=\"corr-panel-head\">\n          <h3>Compose for selected (<span id=\"compose-count\">0</span>)</h3>\n        </div>\n        <div id=\"compose-body\">\n          <label class=\"fld\">Template<select id=\"compose-template\"><option value=\"\">\u2014 choose a template \u2014</option></select></label>\n          <div class=\"grid2\">\n            <label class=\"fld\">Your name<input type=\"text\" id=\"sender-name\" placeholder=\"Lizzie Lopez\"></label>\n            <label class=\"fld\">Your title<input type=\"text\" id=\"sender-title\" placeholder=\"Founder & Principal, Heaven Holdings\"></label>\n          </div>\n          <div id=\"compose-list\"></div>\n          <div class=\"mark-contacted-row\">\n            <label><input type=\"checkbox\" id=\"mark-contacted\"> Mark these as \"Contacted\" after sending</label>\n          </div>\n        </div>\n      </div>\n\n    </div>\n  </div>\n</div>\n\n<div id=\"modal-bg\">\n  <div id=\"modal\">\n    <h3>Copy email addresses</h3>\n    <textarea id=\"modal-emails\" readonly></textarea>\n    <div class=\"mrow\">\n      <button class=\"btn-ghost\" id=\"modal-close\">Close</button>\n      <button class=\"btn-primary\" id=\"modal-copy\">Copy to clipboard</button>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  var STATUSES = [\"Not Contacted\",\"Contacted\",\"In Conversation\",\"Reviewing Deck\",\"Interested\",\"Committed\",\"Passed\",\"Dormant\"];\n  var STATUS_COLORS = {\n    \"Not Contacted\": \"#5B6478\",\n    \"Contacted\": \"#5B7BB4\",\n    \"In Conversation\": \"#C7A045\",\n    \"Reviewing Deck\": \"#C7A045\",\n    \"Interested\": \"#5FA37C\",\n    \"Committed\": \"#2F7D4F\",\n    \"Passed\": \"#C1594C\",\n    \"Dormant\": \"#5B6478\"\n  };\n\n  var state = { rows: [], selected: {}, search: \"\", statusFilter: \"\" };\n  var corrState = { templates: [], activeTemplateId: null };\n  var teamKey = localStorage.getItem(\"hh_inv_key\") || \"\";\n  var saveTimer = null;\n  var templateSaveTimer = null;\n\n  var DEFAULT_TEMPLATES = [\n    {\n      id: 'tpl_default_email',\n      name: 'Initial Introduction (Email)',\n      type: 'email',\n      subject: 'Heaven Holdings \u2014 A Conversation Worth Having',\n      body: \"Dear {{first_name}},\\n\\nI'm reaching out from Heaven Holdings, a cross-border acquisition and advisory firm operating across North America and the Middle East. We work with family offices, private capital, and strategic partners on lower-middle-market acquisitions in the $2M\\u2013$25M range.\\n\\nI'd welcome the chance to share our current mandate and explore whether there's a fit for {{company}} to participate as a capital partner on upcoming opportunities.\\n\\nWould you be open to a short call in the coming weeks?\\n\\nWarm regards,\\n{{sender_name}}\\n{{sender_title}}\"\n    },\n    {\n      id: 'tpl_default_letter',\n      name: 'Formal Introduction (Letter)',\n      type: 'letter',\n      subject: '',\n      body: \"{{date}}\\n\\n{{contact}}\\n{{company}}\\n{{address}}\\n\\nDear {{first_name}},\\n\\nOn behalf of Heaven Holdings, I am writing to formally introduce our firm and its mandate: acquiring, preserving, and growing lower-middle-market businesses across North America and the Middle East.\\n\\nWe are actively building relationships with family offices, private investors, and strategic capital partners who share our long-term, principal-led approach to acquisitions. I would welcome the opportunity to discuss how {{company}} might participate in our current and upcoming deal flow.\\n\\nI look forward to the possibility of working together.\\n\\nSincerely,\\n\\n{{sender_name}}\\n{{sender_title}}\\nHeaven Holdings\"\n    }\n  ];\n\n  function uid(){ return 'inv_' + Math.random().toString(36).slice(2,10) + Date.now().toString(36); }\n  function tid(){ return 'tpl_' + Math.random().toString(36).slice(2,10) + Date.now().toString(36); }\n\n  function emptyRow(){\n    return { id: uid(), company:\"\", contact:\"\", address:\"\", phone:\"\", email:\"\", status:\"Not Contacted\" };\n  }\n\n  function el(tag, cls, html){\n    var e = document.createElement(tag);\n    if(cls) e.className = cls;\n    if(html !== undefined) e.innerHTML = html;\n    return e;\n  }\n\n  function setBadge(mode){\n    var b = document.getElementById('savebadge');\n    b.className = 'savebadge ' + (mode || '');\n    b.textContent = mode === 'saving' ? 'Saving\u2026' : mode === 'saved' ? 'Saved' : mode === 'error' ? 'Save failed' : '';\n  }\n\n  async function apiGet(){\n    var res = await fetch('/api/data', { headers: { 'x-team-key': teamKey } });\n    if(res.status === 401) throw new Error('unauthorized');\n    if(!res.ok) throw new Error('load failed');\n    var data = await res.json();\n    return data || [];\n  }\n\n  async function apiSave(){\n    setBadge('saving');\n    try{\n      var res = await fetch('/api/data', {\n        method: 'PUT',\n        headers: { 'x-team-key': teamKey, 'content-type': 'application/json' },\n        body: JSON.stringify(state.rows)\n      });\n      if(!res.ok) throw new Error('save failed');\n      setBadge('saved');\n      setTimeout(function(){ setBadge(''); }, 1500);\n    }catch(e){\n      setBadge('error');\n    }\n  }\n\n  function scheduleSave(){\n    clearTimeout(saveTimer);\n    saveTimer = setTimeout(apiSave, 600);\n  }\n\n  async function apiGetTemplates(){\n    try{\n      var res = await fetch('/api/templates', { headers: { 'x-team-key': teamKey } });\n      if(!res.ok) throw new Error('load failed');\n      var data = await res.json();\n      if(!data || !data.length) return DEFAULT_TEMPLATES.slice();\n      return data;\n    }catch(e){\n      return DEFAULT_TEMPLATES.slice();\n    }\n  }\n\n  async function apiSaveTemplates(){\n    setBadge('saving');\n    try{\n      var res = await fetch('/api/templates', {\n        method: 'PUT',\n        headers: { 'x-team-key': teamKey, 'content-type': 'application/json' },\n        body: JSON.stringify(corrState.templates)\n      });\n      if(!res.ok) throw new Error('save failed');\n      setBadge('saved');\n      setTimeout(function(){ setBadge(''); }, 1500);\n    }catch(e){\n      setBadge('error');\n    }\n  }\n\n  function scheduleTemplateSave(){\n    clearTimeout(templateSaveTimer);\n    templateSaveTimer = setTimeout(apiSaveTemplates, 600);\n  }\n\n  function filteredRows(){\n    var q = state.search.trim().toLowerCase();\n    return state.rows.filter(function(r){\n      if(state.statusFilter && r.status !== state.statusFilter) return false;\n      if(!q) return true;\n      return (r.company||\"\").toLowerCase().indexOf(q) > -1 ||\n             (r.contact||\"\").toLowerCase().indexOf(q) > -1 ||\n             (r.email||\"\").toLowerCase().indexOf(q) > -1 ||\n             (r.address||\"\").toLowerCase().indexOf(q) > -1;\n    });\n  }\n\n  function updateStats(){\n    document.getElementById('stat-total').textContent = state.rows.length;\n    var active = state.rows.filter(function(r){ return ['Contacted','In Conversation','Reviewing Deck','Interested','Committed'].indexOf(r.status) > -1; }).length;\n    document.getElementById('stat-active').textContent = active;\n    document.getElementById('stat-selected').textContent = Object.keys(state.selected).filter(function(k){return state.selected[k];}).length;\n  }\n\n  function render(){\n    var tbody = document.getElementById('tbody');\n    tbody.innerHTML = '';\n    var rows = filteredRows();\n    document.getElementById('empty-msg').style.display = rows.length === 0 ? 'block' : 'none';\n    rows.forEach(function(r){\n      var tr = document.createElement('tr');\n\n      var tdCheck = el('td','col-check');\n      var cb = document.createElement('input');\n      cb.type = 'checkbox';\n      cb.checked = !!state.selected[r.id];\n      cb.addEventListener('change', function(){\n        if(cb.checked) state.selected[r.id] = true; else delete state.selected[r.id];\n        updateStats(); updateActionButtons();\n      });\n      tdCheck.appendChild(cb);\n      tr.appendChild(tdCheck);\n\n      function textCell(field, placeholder){\n        var td = document.createElement('td');\n        var inp = document.createElement('input');\n        inp.value = r[field] || '';\n        inp.placeholder = placeholder || '';\n        inp.addEventListener('input', function(){ r[field] = inp.value; scheduleSave(); });\n        td.appendChild(inp);\n        return td;\n      }\n\n      tr.appendChild(textCell('company','Company / Office name'));\n      tr.appendChild(textCell('contact','Contact person'));\n\n      var tdAddr = document.createElement('td');\n      var taAddr = document.createElement('textarea');\n      taAddr.value = r.address || '';\n      taAddr.rows = 1;\n      taAddr.addEventListener('input', function(){ r.address = taAddr.value; scheduleSave(); });\n      tdAddr.appendChild(taAddr);\n      tr.appendChild(tdAddr);\n\n      tr.appendChild(textCell('phone','+1 ...'));\n      tr.appendChild(textCell('email','name@firm.com'));\n\n      var tdStatus = el('td','col-status');\n      var sel = document.createElement('select');\n      sel.className = 'status-select';\n      STATUSES.forEach(function(s){\n        var opt = document.createElement('option');\n        opt.value = s; opt.textContent = s;\n        if(s === r.status) opt.selected = true;\n        sel.appendChild(opt);\n      });\n      function paintStatus(){\n        var c = STATUS_COLORS[sel.value] || '#5B6478';\n        sel.style.color = c;\n        sel.style.background = 'rgba(255,255,255,0.03)';\n        sel.style.borderColor = c;\n      }\n      paintStatus();\n      sel.addEventListener('change', function(){ r.status = sel.value; paintStatus(); scheduleSave(); updateStats(); });\n      tdStatus.appendChild(sel);\n      tr.appendChild(tdStatus);\n\n      var tdAct = el('td','col-actions');\n      var del = document.createElement('button');\n      del.className = 'xbtn';\n      del.title = 'Remove';\n      del.innerHTML = '&times;';\n      del.addEventListener('click', function(){\n        if(!confirm('Remove ' + (r.company || 'this entry') + '?')) return;\n        state.rows = state.rows.filter(function(x){ return x.id !== r.id; });\n        delete state.selected[r.id];\n        scheduleSave(); render(); updateStats();\n      });\n      tdAct.appendChild(del);\n      tr.appendChild(tdAct);\n\n      tbody.appendChild(tr);\n    });\n    document.getElementById('rowcount').textContent = rows.length + ' of ' + state.rows.length + ' entries shown';\n    updateStats();\n    updateActionButtons();\n  }\n\n  function updateActionButtons(){\n    var n = Object.keys(state.selected).filter(function(k){return state.selected[k];}).length;\n    document.getElementById('btn-email').disabled = n === 0;\n    document.getElementById('btn-copyemails').disabled = n === 0;\n    document.getElementById('btn-compose').disabled = n === 0;\n  }\n\n  function selectedRows(){\n    return state.rows.filter(function(r){ return state.selected[r.id]; });\n  }\n\n  function csvEscape(v){\n    v = (v === undefined || v === null) ? '' : String(v);\n    if(/[\",\\\\n]/.test(v)) return '\"' + v.replace(/\"/g,'\"\"') + '\"';\n    return v;\n  }\n\n  function exportCsv(){\n    var header = ['Company/Office','Contact Person','Office Address','Phone','Email','Status'];\n    var lines = [header.join(',')];\n    state.rows.forEach(function(r){\n      lines.push([r.company,r.contact,r.address,r.phone,r.email,r.status].map(csvEscape).join(','));\n    });\n    var blob = new Blob([lines.join('\\\\r\\\\n')], {type:'text/csv;charset=utf-8'});\n    var a = document.createElement('a');\n    a.href = URL.createObjectURL(blob);\n    a.download = 'heaven-holdings-investor-network.csv';\n    a.click();\n  }\n\n  function parseCsvLine(line){\n    var out = []; var cur = ''; var inQ = false;\n    for(var i=0;i<line.length;i++){\n      var c = line[i];\n      if(inQ){\n        if(c === '\"' && line[i+1] === '\"'){ cur += '\"'; i++; }\n        else if(c === '\"'){ inQ = false; }\n        else cur += c;\n      } else {\n        if(c === '\"') inQ = true;\n        else if(c === ','){ out.push(cur); cur=''; }\n        else cur += c;\n      }\n    }\n    out.push(cur);\n    return out;\n  }\n\n  function importCsv(text){\n    var lines = text.replace(/\\\\r/g,'').split('\\\\n').filter(function(l){return l.trim().length;});\n    if(!lines.length) return;\n    var startIdx = 0;\n    var first = parseCsvLine(lines[0]).map(function(s){return s.trim().toLowerCase();});\n    if(first[0] && first[0].indexOf('company') > -1) startIdx = 1;\n    var added = 0;\n    for(var i=startIdx;i<lines.length;i++){\n      var cols = parseCsvLine(lines[i]);\n      if(!cols.some(function(c){return c && c.trim();})) continue;\n      var row = emptyRow();\n      row.company = cols[0] || '';\n      row.contact = cols[1] || '';\n      row.address = cols[2] || '';\n      row.phone = cols[3] || '';\n      row.email = cols[4] || '';\n      row.status = STATUSES.indexOf(cols[5]) > -1 ? cols[5] : 'Not Contacted';\n      state.rows.push(row);\n      added++;\n    }\n    scheduleSave(); render();\n    alert('Imported ' + added + ' entr' + (added===1?'y':'ies') + '.');\n  }\n\n  function buildMailto(rows){\n    var emails = rows.map(function(r){ return (r.email||'').trim(); }).filter(Boolean);\n    if(!emails.length) return null;\n    return 'mailto:?bcc=' + encodeURIComponent(emails.join(',')) + '&subject=' + encodeURIComponent('Heaven Holdings') + '&body=' + encodeURIComponent('');\n  }\n\n  function initStatusFilter(){\n    var sel = document.getElementById('filter-status');\n    STATUSES.forEach(function(s){\n      var opt = document.createElement('option');\n      opt.value = s; opt.textContent = s;\n      sel.appendChild(opt);\n    });\n  }\n\n  /* ---------------- Correspondence ---------------- */\n\n  function firstName(name){\n    name = (name || '').trim();\n    if(!name) return '';\n    return name.split(/\\s+/)[0];\n  }\n\n  function todayLong(){\n    var d = new Date();\n    return d.toLocaleDateString(undefined, { year:'numeric', month:'long', day:'numeric' });\n  }\n\n  function mergeTemplate(str, row){\n    var senderName = document.getElementById('sender-name').value.trim();\n    var senderTitle = document.getElementById('sender-title').value.trim();\n    var map = {\n      company: row.company || '',\n      contact: row.contact || '',\n      first_name: firstName(row.contact),\n      address: row.address || '',\n      phone: row.phone || '',\n      email: row.email || '',\n      status: row.status || '',\n      date: todayLong(),\n      sender_name: senderName,\n      sender_title: senderTitle\n    };\n    return (str || '').replace(/\\{\\{\\s*(\\w+)\\s*\\}\\}/g, function(m, key){\n      return (key in map) ? map[key] : m;\n    });\n  }\n\n  function findTemplate(id){\n    return corrState.templates.filter(function(t){ return t.id === id; })[0] || null;\n  }\n\n  function renderTemplateList(){\n    var wrap = document.getElementById('template-list');\n    wrap.innerHTML = '';\n    corrState.templates.forEach(function(t){\n      var item = document.createElement('div');\n      item.className = 'tpl-item' + (t.id === corrState.activeTemplateId ? ' on' : '');\n      item.innerHTML = '<span>' + escapeHtml(t.name || '(untitled)') + '</span>' +\n        '<span class=\"tpl-badge\">' + (t.type === 'letter' ? 'Letter' : 'Email') + '</span>';\n      item.addEventListener('click', function(){\n        corrState.activeTemplateId = t.id;\n        renderTemplateList();\n        renderEditor();\n      });\n      wrap.appendChild(item);\n    });\n    renderComposeTemplateOptions();\n  }\n\n  function escapeHtml(s){\n    var d = document.createElement('div');\n    d.textContent = s || '';\n    return d.innerHTML;\n  }\n\n  function renderEditor(){\n    var t = findTemplate(corrState.activeTemplateId);\n    var body = document.getElementById('editor-body');\n    var empty = document.getElementById('editor-empty');\n    var delBtn = document.getElementById('btn-delete-template');\n    var saveBtn = document.getElementById('btn-save-template');\n    if(!t){\n      body.style.display = 'none';\n      empty.style.display = 'block';\n      delBtn.disabled = true;\n      saveBtn.disabled = true;\n      return;\n    }\n    body.style.display = 'block';\n    empty.style.display = 'none';\n    delBtn.disabled = false;\n    saveBtn.disabled = false;\n    document.getElementById('tpl-name').value = t.name || '';\n    document.getElementById('tpl-type').value = t.type || 'email';\n    document.getElementById('tpl-subject').value = t.subject || '';\n    document.getElementById('tpl-body').value = t.body || '';\n    document.getElementById('tpl-subject-wrap').style.display = (t.type === 'letter') ? 'none' : 'block';\n  }\n\n  function renderComposeTemplateOptions(){\n    var sel = document.getElementById('compose-template');\n    var current = sel.value;\n    sel.innerHTML = '<option value=\"\">\u2014 choose a template \u2014</option>';\n    corrState.templates.forEach(function(t){\n      var opt = document.createElement('option');\n      opt.value = t.id;\n      opt.textContent = t.name + ' (' + (t.type === 'letter' ? 'Letter' : 'Email') + ')';\n      sel.appendChild(opt);\n    });\n    if(findTemplate(current)) sel.value = current;\n  }\n\n  function renderComposeList(){\n    var rows = selectedRows();\n    document.getElementById('compose-count').textContent = rows.length;\n    var tplId = document.getElementById('compose-template').value;\n    var tpl = findTemplate(tplId);\n    var list = document.getElementById('compose-list');\n    list.innerHTML = '';\n\n    if(!tpl){\n      list.innerHTML = '<div class=\"card-note\">Choose a template above to preview merged correspondence for each selected entry.</div>';\n      return;\n    }\n\n    if(tpl.type === 'letter'){\n      var actions = document.createElement('div');\n      actions.id = 'corr-letters-actions';\n      var printBtn = document.createElement('button');\n      printBtn.className = 'btn-primary';\n      printBtn.textContent = 'Print / save all as PDF';\n      printBtn.addEventListener('click', function(){ printLetters(rows, tpl); });\n      actions.appendChild(printBtn);\n      list.appendChild(actions);\n    }\n\n    rows.forEach(function(r){\n      var card = document.createElement('div');\n      card.className = 'compose-card' + (!r.email && tpl.type === 'email' ? ' noemail' : '');\n      var mergedBody = mergeTemplate(tpl.body, r);\n      var mergedSubject = mergeTemplate(tpl.subject, r);\n      var head = '<div class=\"cc-head\"><span class=\"cc-name\">' + escapeHtml(r.company || r.contact || '(unnamed)') + '</span><span class=\"cc-email\">' + escapeHtml(r.email || 'no email on file') + '</span></div>';\n      var subjectLine = tpl.type === 'email' ? '<div class=\"cc-subject\"><b>Subject:</b> ' + escapeHtml(mergedSubject) + '</div>' : '';\n      card.innerHTML = head + subjectLine + '<pre>' + escapeHtml(mergedBody) + '</pre>';\n\n      var actionsRow = document.createElement('div');\n      actionsRow.className = 'cc-actions';\n\n      if(tpl.type === 'email'){\n        var sendBtn = document.createElement('button');\n        sendBtn.className = 'btn-primary sm';\n        sendBtn.textContent = 'Open in email app';\n        sendBtn.addEventListener('click', function(){\n          var link = 'mailto:' + encodeURIComponent(r.email) + '?subject=' + encodeURIComponent(mergedSubject) + '&body=' + encodeURIComponent(mergedBody);\n          window.open(link, '_blank');\n          maybeMarkContacted([r]);\n        });\n        actionsRow.appendChild(sendBtn);\n        if(!r.email){\n          var warn = document.createElement('div');\n          warn.className = 'cc-warn';\n          warn.textContent = 'No email address on file for this entry.';\n          card.appendChild(warn);\n        }\n      } else {\n        var printOneBtn = document.createElement('button');\n        printOneBtn.className = 'btn-ghost sm';\n        printOneBtn.textContent = 'Print this letter';\n        printOneBtn.addEventListener('click', function(){\n          printLetters([r], tpl);\n          maybeMarkContacted([r]);\n        });\n        actionsRow.appendChild(printOneBtn);\n      }\n      card.appendChild(actionsRow);\n      list.appendChild(card);\n    });\n  }\n\n  function maybeMarkContacted(rows){\n    if(!document.getElementById('mark-contacted').checked) return;\n    rows.forEach(function(r){\n      if(r.status === 'Not Contacted') r.status = 'Contacted';\n    });\n    scheduleSave();\n  }\n\n  function printLetters(rows, tpl){\n    var win = window.open('', '_blank');\n    var pages = rows.map(function(r){\n      var merged = mergeTemplate(tpl.body, r);\n      return '<div class=\"letter-page\">' +\n        '<div class=\"letter-head\"><img src=\"data:image/jpeg;base64,\"><div><div class=\"lh-name\">Heaven Holdings</div><div class=\"lh-sub\">An Acquisition \\u2014 M&A Holding Company of CAMENAEU Inc.</div></div></div>' +\n        '<div class=\"letter-body\">' + escapeHtml(merged).replace(/\\n/g,'<br>') + '</div>' +\n        '</div>';\n    }).join('');\n    var doc = '<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><title>Heaven Holdings \u2014 Letters</title><style>' +\n      \"@import url('https://fonts.googleapis.com/css2?family=Source+Serif+4:opsz,wght@8..60,400;8..60,600&family=Inter:wght@400;500&display=swap');\" +\n      'body{font-family:\"Inter\",sans-serif; color:#1a1a1a; margin:0;}' +\n      '.letter-page{page-break-after:always; padding:60px 70px; min-height:90vh; box-sizing:border-box;}' +\n      '.letter-page:last-child{page-break-after:auto;}' +\n      '.letter-head{display:flex; align-items:center; gap:16px; border-bottom:2px solid #C7A045; padding-bottom:18px; margin-bottom:36px;}' +\n      '.letter-head img{width:48px; height:48px; border-radius:50%; object-fit:cover;}' +\n      '.lh-name{font-family:\"Source Serif 4\",serif; font-size:20px; font-weight:600; color:#0A0F1C;}' +\n      '.lh-sub{font-size:11px; color:#666; letter-spacing:0.03em; margin-top:2px;}' +\n      '.letter-body{font-size:14px; line-height:1.9; white-space:pre-wrap;}' +\n      '@media print{ body{ -webkit-print-color-adjust:exact; } }' +\n      '</style></head><body>' + pages + '<script>window.onload=function(){setTimeout(function(){window.print();},300);};<' + '/script></body></html>';\n    win.document.write(doc);\n    win.document.close();\n  }\n\n  function wireCorrespondenceEvents(){\n    document.getElementById('tab-directory').addEventListener('click', function(){ switchView('directory'); });\n    document.getElementById('tab-correspondence').addEventListener('click', function(){ switchView('correspondence'); });\n\n    document.getElementById('btn-compose').addEventListener('click', function(){ switchView('correspondence'); });\n\n    document.getElementById('btn-new-template').addEventListener('click', function(){\n      var t = { id: tid(), name: 'New template', type: 'email', subject: '', body: '' };\n      corrState.templates.unshift(t);\n      corrState.activeTemplateId = t.id;\n      renderTemplateList(); renderEditor();\n      scheduleTemplateSave();\n    });\n\n    document.getElementById('btn-delete-template').addEventListener('click', function(){\n      var t = findTemplate(corrState.activeTemplateId);\n      if(!t) return;\n      if(!confirm('Delete template \"' + (t.name || 'this template') + '\"?')) return;\n      corrState.templates = corrState.templates.filter(function(x){ return x.id !== t.id; });\n      corrState.activeTemplateId = null;\n      renderTemplateList(); renderEditor();\n      scheduleTemplateSave();\n    });\n\n    document.getElementById('btn-save-template').addEventListener('click', function(){\n      var t = findTemplate(corrState.activeTemplateId);\n      if(!t) return;\n      t.name = document.getElementById('tpl-name').value.trim() || 'Untitled';\n      t.type = document.getElementById('tpl-type').value;\n      t.subject = document.getElementById('tpl-subject').value;\n      t.body = document.getElementById('tpl-body').value;\n      renderTemplateList();\n      apiSaveTemplates();\n      renderComposeList();\n    });\n\n    document.getElementById('tpl-type').addEventListener('change', function(){\n      document.getElementById('tpl-subject-wrap').style.display = (this.value === 'letter') ? 'none' : 'block';\n    });\n\n    Array.prototype.forEach.call(document.querySelectorAll('.tokchip'), function(chip){\n      chip.addEventListener('click', function(){\n        var ta = document.getElementById('tpl-body');\n        var tok = chip.getAttribute('data-t');\n        var start = ta.selectionStart || ta.value.length;\n        var end = ta.selectionEnd || ta.value.length;\n        ta.value = ta.value.slice(0, start) + tok + ta.value.slice(end);\n        ta.focus();\n        ta.selectionStart = ta.selectionEnd = start + tok.length;\n      });\n    });\n\n    document.getElementById('compose-template').addEventListener('change', renderComposeList);\n    document.getElementById('sender-name').addEventListener('input', function(){\n      localStorage.setItem('hh_inv_sender_name', this.value);\n      renderComposeList();\n    });\n    document.getElementById('sender-title').addEventListener('input', function(){\n      localStorage.setItem('hh_inv_sender_title', this.value);\n      renderComposeList();\n    });\n  }\n\n  function switchView(view){\n    var isDir = view === 'directory';\n    document.getElementById('view-directory').style.display = isDir ? 'block' : 'none';\n    document.getElementById('view-correspondence').style.display = isDir ? 'none' : 'block';\n    document.getElementById('tab-directory').classList.toggle('on', isDir);\n    document.getElementById('tab-correspondence').classList.toggle('on', !isDir);\n    if(!isDir) renderComposeList();\n  }\n\n  function wireEvents(){\n    document.getElementById('search').addEventListener('input', function(e){ state.search = e.target.value; render(); });\n    document.getElementById('filter-status').addEventListener('change', function(e){ state.statusFilter = e.target.value; render(); });\n\n    document.getElementById('check-header').addEventListener('change', function(e){\n      filteredRows().forEach(function(r){\n        if(e.target.checked) state.selected[r.id] = true; else delete state.selected[r.id];\n      });\n      render();\n    });\n\n    document.getElementById('btn-selectall').addEventListener('click', function(){\n      filteredRows().forEach(function(r){ state.selected[r.id] = true; });\n      render();\n    });\n    document.getElementById('btn-clearsel').addEventListener('click', function(){\n      state.selected = {}; render();\n    });\n\n    document.getElementById('btn-add').addEventListener('click', function(){\n      var r = emptyRow();\n      state.rows.unshift(r);\n      scheduleSave(); render();\n    });\n\n    document.getElementById('btn-email').addEventListener('click', function(){\n      var rows = selectedRows();\n      var link = buildMailto(rows);\n      if(!link){ alert('None of the selected entries have an email address.'); return; }\n      window.location.href = link;\n    });\n\n    document.getElementById('btn-copyemails').addEventListener('click', function(){\n      var rows = selectedRows();\n      var emails = rows.map(function(r){return (r.email||'').trim();}).filter(Boolean);\n      document.getElementById('modal-emails').value = emails.join(', ');\n      document.getElementById('modal-bg').classList.add('show');\n    });\n    document.getElementById('modal-close').addEventListener('click', function(){\n      document.getElementById('modal-bg').classList.remove('show');\n    });\n    document.getElementById('modal-copy').addEventListener('click', function(){\n      var ta = document.getElementById('modal-emails');\n      ta.select();\n      document.execCommand('copy');\n    });\n\n    document.getElementById('btn-export').addEventListener('click', exportCsv);\n    document.getElementById('btn-import').addEventListener('click', function(){\n      document.getElementById('file-import').click();\n    });\n    document.getElementById('file-import').addEventListener('change', function(e){\n      var file = e.target.files && e.target.files[0];\n      if(!file) return;\n      var reader = new FileReader();\n      reader.onload = function(){ importCsv(reader.result); };\n      reader.readAsText(file);\n      e.target.value = '';\n    });\n\n    wireCorrespondenceEvents();\n  }\n\n  async function boot(){\n    initStatusFilter();\n    wireEvents();\n    document.getElementById('sender-name').value = localStorage.getItem('hh_inv_sender_name') || '';\n    document.getElementById('sender-title').value = localStorage.getItem('hh_inv_sender_title') || '';\n    try{\n      state.rows = await apiGet();\n      corrState.templates = await apiGetTemplates();\n      document.getElementById('gate').style.display = 'none';\n      document.getElementById('app').style.display = 'block';\n      render();\n      renderTemplateList();\n      renderEditor();\n    }catch(e){\n      showGateError('Wrong key, or the server isn\\\\'t set up yet.');\n    }\n  }\n\n  function showGateError(msg){\n    document.getElementById('gate-err').textContent = msg;\n  }\n\n  document.getElementById('gate-btn').addEventListener('click', async function(){\n    teamKey = document.getElementById('gate-key').value.trim();\n    if(!teamKey){ showGateError('Enter your access key.'); return; }\n    localStorage.setItem('hh_inv_key', teamKey);\n    showGateError('');\n    boot();\n  });\n  document.getElementById('gate-key').addEventListener('keydown', function(e){\n    if(e.key === 'Enter') document.getElementById('gate-btn').click();\n  });\n\n  if(teamKey){\n    boot();\n  }\n})();\n</script>\n</body>\n</html>\n";
